// Build shares for the loop simulation (T132's "The win table", "Racing"): how far an Uma is
// through her scenario's layer, and which of the layer's unlocks a share of it holds. The win table (generated by
// scripts/sim/loop-wins.ts) races a build at these shares; the loop reads her share when she races.
import { FACILITY_IDS } from '../farm/buildings'
import { isOpen } from '../training/order'
import { BONDS_BY_SCENARIO, bondsThrough, facilityOf, LAYER_SIZES, layerUnlocks, type Unlock } from '../training/unlocks'
import type { ScenarioOfTier, UmaBuild } from '../state/types'

/** The win table's build shares: none of her layer, half and all of it (T132). */
export const WIN_SHARES = Object.freeze([0, 0.5, 1] as const)

/**
 * Her share of scenario s's layer, 0–1: its fixed unlocks open, plus her bonds past the earlier layers' pacing count up
 * to this layer's (06 §2), over the layer's size (27, 23, 21, 19, 17).
 */
export function layerShare(build: UmaBuild, scenario: ScenarioOfTier): number {
  const fixed = layerUnlocks(scenario).filter((entry) => isOpen(build, entry)).length
  const earlier = scenario > 1 ? bondsThrough((scenario - 1) as ScenarioOfTier) : 0
  const bonds = Math.min(BONDS_BY_SCENARIO[scenario - 1]!, Math.max(0, build.bonds.length - earlier))
  return (fixed + bonds) / LAYER_SIZES[scenario - 1]!.total
}

/**
 * Layer s's fixed unlocks at `share` of it: that share of each facility's, rounded, in the layer's canonical order, so
 * every unlock's dependencies come before it (05 §3).
 */
export function layerPart(s: ScenarioOfTier, share: number): readonly Unlock[] {
  if (!(share >= 0 && share <= 1)) throw new RangeError(`A build share is 0–1: ${share}`)
  const all = layerUnlocks(s)
  return FACILITY_IDS.flatMap((facility) => {
    const here = all.filter((entry) => facilityOf(entry.kind) === facility)
    return here.slice(0, Math.round(share * here.length))
  })
}
